<#
    Compiles and runs BepInExVersionCheck against a built dll.

        ./test-bepinex-version.ps1 -Assembly bin/ScamWYF.ModHandler.dll

    build.ps1 calls this after every compile, so a mod whose [BepInPlugin] version BepInEx cannot parse
    fails the build rather than shipping. See BepInExVersionCheck.cs for why that failure is otherwise
    invisible: BepInEx logs it and loads nothing, and says so in no other place.

    -Cecil is passed in by build.ps1 because the copy in BepInEx/core is the one already resolved for the
    compile; this falls back to the same place build.ps1 would when run by hand.

    Two ways to run the check, because the tool it compiles has to run somewhere:

      * Windows: a tiny .NET Framework exe, compiled against the reference assemblies that ship with
        Visual Studio. This is what it always did.
      * Everywhere else - and on a Windows machine with only the .NET SDK: a throwaway SDK project in
        obj/, run with `dotnet run`. .NET Framework reference assemblies do not exist off Windows, and
        the SDK is the one thing a Linux build is guaranteed to have.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)][string[]]$Assembly,
    [string]$Cecil,
    [string]$CscDll
)

$ErrorActionPreference = 'Stop'

foreach ($a in $Assembly) { if (-not (Test-Path $a)) { throw "No such assembly: $a" } }

# Windows PowerShell 5.1 has no $IsWindows; its absence is itself the answer.
$onWindows = if ($null -ne $IsWindows) { $IsWindows } else { $env:OS -eq 'Windows_NT' }

function Resolve-ToolCompiler {
    param([string]$Explicit)
    if ($Explicit) { return $Explicit }

    foreach ($root in @("${env:ProgramFiles}/dotnet/sdk", "$env:USERPROFILE/.dotnet/sdk",
                        "$env:HOME/.dotnet/sdk", '/usr/lib/dotnet/sdk', '/usr/share/dotnet/sdk')) {
        if (-not $root -or -not (Test-Path $root)) { continue }
        $dll = Get-ChildItem -Path (Join-Path $root '*/Roslyn/bincore/csc.dll') -ErrorAction SilentlyContinue |
            Sort-Object FullName -Descending | Select-Object -First 1
        if ($dll) { return $dll.FullName }
    }

    return $null
}

if (-not $Cecil) {
    # Same order build.ps1 uses: a copy staged beside this script, then the game's BepInEx/core. Running
    # by hand from a mod repo, the staged path does not exist and the game's does.
    foreach ($root in @($PSScriptRoot, (Join-Path $PSScriptRoot '..'), (Join-Path $PSScriptRoot '../..'))) {
        $candidate = Join-Path $root 'vendor/Mono.Cecil.dll'
        if (Test-Path $candidate) { $Cecil = (Resolve-Path $candidate).Path; break }
    }
}

if (-not $Cecil) {
    # The game's own copy, found the same way build.ps1 finds it - SWYG_GAME_DIR, then Steam - rather
    # than a drive letter written into a tool.
    try {
        . (Join-Path $PSScriptRoot '../GameDir.ps1')
        $candidate = Join-Path (Resolve-GameDir -Require BepInEx) 'BepInEx/core/Mono.Cecil.dll'
        if (Test-Path $candidate) { $Cecil = $candidate }
    } catch {
        # No game found. The caller is expected to pass -Cecil, and the check below says so.
    }
}

$source = Join-Path $PSScriptRoot 'BepInExVersionCheck.cs'
$outDir = Join-Path $PSScriptRoot '../obj/tools'
New-Item -ItemType Directory -Force -Path $outDir | Out-Null

<#
    The SDK path. A generated project rather than a hand-rolled csc invocation, so the runtime config,
    the reference set and the exit code all come from the SDK instead of from this script guessing at
    the layout of the machine's dotnet installation.
#>
function Invoke-WithDotnetProject {
    $dotnet = Get-Command dotnet -ErrorAction SilentlyContinue
    if (-not $dotnet) { return $null }

    if (-not $Cecil -or -not (Test-Path $Cecil)) {
        throw "No Mono.Cecil.dll. build.ps1 passes the one from BepInEx/core; pass -Cecil when running this by hand."
    }

    # The tool follows the SDK that is installed, rather than naming a framework the machine may not
    # have. `dotnet --version` is the SDK's own idea of which one that is.
    $tfm = 'net' + ((& dotnet --version).Trim() -split '\.')[0] + '.0'

    $projectDir = Join-Path $outDir 'versioncheck'
    New-Item -ItemType Directory -Force -Path $projectDir | Out-Null
    $project = Join-Path $projectDir 'VersionCheck.csproj'

    @"
<Project Sdk="Microsoft.NET.Sdk">
  <!-- Generated by tools/test-bepinex-version.ps1. Not committed: obj/ is gitignored. -->
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>$tfm</TargetFramework>
    <Nullable>disable</Nullable>
    <ImplicitUsings>disable</ImplicitUsings>
    <AssemblyName>BepInExVersionCheck</AssemblyName>
    <EnableDefaultCompileItems>false</EnableDefaultCompileItems>
    <InvariantGlobalization>true</InvariantGlobalization>
  </PropertyGroup>
  <ItemGroup>
    <Compile Include="$source" />
    <!-- The game's Cecil, handed in, rather than a NuGet fetch: the build is meant to work offline
         and with only the game's own assemblies. -->
    <Reference Include="Mono.Cecil"><HintPath>$Cecil</HintPath></Reference>
  </ItemGroup>
</Project>
"@ | Set-Content -LiteralPath $project -Encoding UTF8

    # Build and then run the dll directly, rather than `dotnet run`: every argument after a bare `--`
    # is the application's, but an option `dotnet run` does not itself recognise is passed through to
    # the application too, which is how `--nologo` ended up being checked as a dll name.
    #
    # The build output is held back. A success prints nothing, because a mod build's log is about the
    # mod; a failure prints all of it, because why the tool would not compile is the only thing worth
    # reading at that point.
    $build = & dotnet build $project -c Release --nologo -v quiet 2>&1
    if ($LASTEXITCODE -ne 0) {
        $build | Out-Host
        throw "BepInExVersionCheck failed to build (exit $LASTEXITCODE)"
    }

    $tool = Join-Path $projectDir "bin/Release/$tfm/BepInExVersionCheck.dll"
    if (-not (Test-Path $tool)) { throw "The version check did not build: $tool" }

    & dotnet $tool @Assembly | Out-Host
    return $LASTEXITCODE
}

<#
    The Windows path: compile a .NET Framework exe with Roslyn and run it directly. Kept because a
    Windows machine with only VS Build Tools has no SDK to fall back on.
#>
function Invoke-WithFrameworkExe {
    $frameworkBase = if (${env:ProgramFiles(x86)}) {
        Join-Path ${env:ProgramFiles(x86)} 'Reference Assemblies/Microsoft/Framework/.NETFramework'
    }

    if (-not $frameworkBase -or -not (Test-Path $frameworkBase)) { return $null }

    $refRoot = Join-Path $frameworkBase 'v4.8'
    if (-not (Test-Path $refRoot)) {
        $found = Get-ChildItem $frameworkBase -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -match '^v(\d+)\.(\d+)' } |
            Sort-Object { [version]$_.Name.TrimStart('v') } -Descending |
            Select-Object -First 1
        if ($found) { $refRoot = $found.FullName }
    }
    if (-not (Test-Path $refRoot)) { return $null }

    if (-not $Cecil -or -not (Test-Path $Cecil)) {
        throw "No Mono.Cecil.dll. build.ps1 passes the one from BepInEx/core; pass -Cecil when running this by hand."
    }

    $csc = Resolve-ToolCompiler $CscDll
    if (-not $csc) { return $null }

    $exe = Join-Path $outDir 'BepInExVersionCheck.exe'

    $references = @(
        (Join-Path $refRoot 'mscorlib.dll')
        $Cecil
    )
    foreach ($r in $references) { if (-not (Test-Path $r)) { throw "Missing reference: $r" } }

    $compilerArgs = @(
        '-target:exe'
        '-platform:anycpu'
        '-nostdlib+'
        '-langversion:7.3'
        '-optimize+'
        '-warn:4'
        '-main:ScamWYF.Modding.Tools.BepInExVersionCheck'
        "-out:$exe"
        ($references | ForEach-Object { "-reference:$_" })
        $source
    )

    if ($csc -like '*.dll') { & dotnet $csc @compilerArgs } else { & $csc @compilerArgs }
    if ($LASTEXITCODE -ne 0) { throw "BepInExVersionCheck failed to compile (exit $LASTEXITCODE)" }

    # Beside the exe, or it compiles against Cecil fine and then fails to load it at run time.
    Copy-Item $Cecil (Join-Path $outDir 'Mono.Cecil.dll') -Force

    & $exe $Assembly | Out-Host
    return $LASTEXITCODE
}

$exit = $null
if ($onWindows) { $exit = Invoke-WithFrameworkExe }
if ($null -eq $exit) { $exit = Invoke-WithDotnetProject }

exit $exit
